function navigate(next){if(!Object.hasOwn(views,next))return;view=next;location.hash=next;$('module-nav').classList.remove('nav-expanded');$('mobile-menu').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});}
function applyAppearance(){document.documentElement.dataset.theme=appearance.theme;document.body.dataset.photoMode=photoBlob?appearance.photoMode:'none';$('personal-frame').hidden=!photoBlob||appearance.photoMode!=='frame';document.querySelector('.sidebar').classList.toggle('has-frame',!!photoBlob&&appearance.photoMode==='frame');}
