function photoStore(mode,operation){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('Este navegador no permite conservar fotografías locales.'));return;}const request=indexedDB.open('compas-personal-appearance',1);request.onupgradeneeded=()=>request.result.createObjectStore('assets');request.onerror=()=>reject(new Error('No se pudo abrir el almacenamiento de la foto.'));request.onblocked=()=>reject(new Error('Cierra otras pestañas de Compás e intenta de nuevo.'));request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>db.close();let value;try{const tx=db.transaction('assets',mode),r=operation(tx.objectStore('assets'));r.onsuccess=()=>value=r.result;tx.oncomplete=()=>{db.close();resolve(value);};tx.onerror=tx.onabort=()=>{db.close();reject(new Error('No se pudo guardar la foto en este navegador.'));};}catch(err){db.close();reject(err);}};});}
function showPhoto(blob){if(photoURL)URL.revokeObjectURL(photoURL);photoBlob=blob;photoURL=blob?URL.createObjectURL(blob):'';for(const id of ['personal-image','ambient-image']){if(photoURL)$(id).src=photoURL;else $(id).removeAttribute('src');}applyAppearance();}
async function compressPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Elige una imagen JPG, PNG o WebP.');if(file.size>20*1024*1024)throw new Error('Elige una imagen menor de 20 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.naturalWidth||!img.naturalHeight)throw new Error('La imagen no se pudo leer.');const ratio=Math.min(1,1400/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('El navegador no pudo preparar la fotografía.');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.8));if(!blob||blob.size>=2*1024*1024)throw new Error('No se pudo preparar una imagen ligera. Intenta con otra foto.');return blob;}finally{URL.revokeObjectURL(url);}}
function appearanceStatus(message){if($('appearance-status'))$('appearance-status').textContent=message;else toast(message);}
function appearanceDialog(refresh=false){const d=$('editor');d.classList.remove('todo-import-dialog');if(!refresh)dialogTrigger=document.activeElement;d.classList.add('appearance-dialog');d.innerHTML='<div class="dialog-top"><div><h2 id="dialog-title">Tu espacio de trabajo</h2><p class="hint">Elige un ambiente que te ayude a concentrarte.</p></div>'+btn('Cerrar','close','','ghost')+'</div><div class="dialog-body"><h3>Tema</h3><div class="theme-grid">'+Object.entries(THEMES).map(([key,label])=>'<button type="button" class="theme-choice" data-do="theme" data-theme="'+key+'" aria-pressed="'+(appearance.theme===key)+'"><span class="theme-swatch '+key+'" aria-hidden="true"></span>'+label+'</button>').join('')+'</div><h3>Tu portarretratos o fondo</h3><div class="photo-preview">'+(photoURL?'<img src="'+e(photoURL)+'" alt="Vista previa de tu foto">':'<div class="photo-placeholder" aria-hidden="true">+</div>')+'<div><p class="hint">Elige una foto para activar el portarretratos. También puedes usarla como fondo suave.</p><div class="toolbar" style="margin-top:10px">'+btn(photoBlob?'Cambiar foto':'Elegir foto','choose-photo','','compact')+(photoBlob?btn('Quitar','remove-photo','','ghost compact'):'')+'</div></div></div><div class="photo-modes" role="group" aria-label="Cómo mostrar tu foto">'+[['none','Sin foto'],['frame','Portarretratos'],['background','Fondo suave']].map(([v,label])=>'<label><input type="radio" name="photo-mode" value="'+v+'"'+(appearance.photoMode===v?' checked':'')+'>'+label+'</label>').join('')+'</div><p class="hint">La foto permanece en este navegador. No se incluye en respaldos ni reportes; si borras los datos del navegador, vuelve a elegirla.</p><p class="appearance-status" id="appearance-status" role="status"></p></div><div class="dialog-bottom">'+btn('Restablecer apariencia','reset-appearance','','ghost')+btn('Listo','close','','primary')+'</div>';if(!d.open)d.showModal();}
applyAppearance();
photoStore('readonly',store=>store.get('photo')).then(blob=>{if(photoRevision===0&&blob instanceof Blob&&blob.type==='image/jpeg'&&blob.size<2*1024*1024)showPhoto(blob);}).catch(()=>{});
function empty(title,text,action){return '<div class="empty"><h3>'+e(title)+'</h3><p>'+e(text)+'</p>'+(action||'')+'</div>';}
