function actionRow(a){const late=a.due&&a.due<C.today()&&a.status!=='resuelto';return '<article class="action-row"><div><div class="action-title">'+e(a.description)+'</div><div class="row-meta"><span>'+e(a.sourceLabel||'Registro personal')+'</span><span class="'+(late?'overdue':'')+'">'+(late?'Por revisar · ':'')+e(fmt(a.due))+'</span><span>Prioridad '+e(a.priority)+'</span></div></div><div class="action-side">'+badge(a.status)+btn('Revisar','action','data-id="'+e(a.id)+'"','compact')+btn('Desglosar en ToDo','todo-edit','data-source="'+e(a.id)+'"','ghost compact')+'</div></article>';}
